#!/usr/bin/env python3
"""Select an extracted Maylang bundle and configure Bash once."""
import argparse
import os
import re
import shlex
import shutil
import sys
import tempfile
from pathlib import Path

START = '# >>> Maylang managed environment >>>'
END = '# <<< Maylang managed environment <<<'
TOOLS = ('mayc', 'may', 'mayfmt', 'maypkg', 'maylsp')


def atomic_write(path, content, mode=0o644):
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as temporary:
        staged = Path(temporary.name)
        try:
            temporary.write(content.encode())
            temporary.flush()
            staged.chmod(mode)
            staged.replace(path)
        finally:
            staged.unlink(missing_ok=True)


def select_bundle(root, selection):
    if selection == 'latest':
        candidates = []
        for path in root.glob('maylang-*-x86_64-linux'):
            match = re.fullmatch(r'maylang-(\d+)\.(\d+)\.(\d+)-x86_64-linux', path.name)
            if match and path.is_dir():
                candidates.append((tuple(map(int, match.groups())), path))
        if not candidates:
            raise ValueError(f'no extracted stable releases in {root}')
        return max(candidates)[1].resolve()
    version = selection.removeprefix('v')
    if re.fullmatch(r'\d+\.\d+\.\d+(?:-[A-Za-z0-9.-]+)?', version):
        return (root / f'maylang-{version}-x86_64-linux').resolve()
    return Path(selection).expanduser().resolve()


def validate_bundle(bundle):
    required = [*(f'bin/{name}' for name in TOOLS), 'bin/runtime.may',
                'bin/native.may', 'bin/prelude.may', 'bin/runtime/core.may', 'bin/runtime/math.may',
                'stdlib/prelude.may', 'VERSION']
    missing = [name for name in required if not (bundle / name).is_file()]
    if missing:
        raise ValueError(f'incomplete bundle {bundle}: missing {", ".join(missing)}')
    version = (bundle / 'VERSION').read_text().strip()
    if not re.fullmatch(r'\d+\.\d+\.\d+(?:-[A-Za-z0-9.-]+)?', version):
        raise ValueError(f'invalid VERSION in {bundle}')
    return version


def bashrc_content(content, root, env_path):
    if content.count(START) != content.count(END) or content.count(START) > 1:
        raise ValueError('malformed Maylang managed block in bashrc')
    if START in content and content.index(START) > content.index(END):
        raise ValueError('malformed Maylang managed block in bashrc')
    content = re.sub(r'^' + re.escape(START) + r'\n.*?^' + re.escape(END) + r'\n?',
                     '', content, flags=re.MULTILINE | re.DOTALL)
    lines = []
    for line in content.splitlines(keepends=True):
        match = re.fullmatch(r'\s*export (PATH|MAYLANG_STDLIB)=(?:"([^"]*)"|\x27([^\x27]*)\x27|(\S+))\s*', line)
        if match:
            value = next(part for part in match.groups()[1:] if part is not None)
            value = value.replace('${HOME}', str(Path.home())).replace('$HOME', str(Path.home()))
            if match[1] == 'PATH':
                value = value.replace('${PATH}', '$PATH')
                old_path = re.fullmatch(re.escape(str(root)) + r'/maylang-[^/:]+/bin:\$PATH', value)
                legacy_path = value == f'{Path.home()}/.maylang/bin:$PATH'
                if old_path or legacy_path or value == f'{root}/current/bin:$PATH':
                    continue
            elif re.fullmatch(re.escape(str(root)) + r'/maylang-[^/:]+/stdlib', value):
                continue
        lines.append(line)
    result = ''.join(lines).rstrip('\n')
    return result + f'\n\n{START}\n. {shlex.quote(str(env_path))}\n{END}\n'


def environment(root, bashrc):
    # Removing old bundle entries also refreshes shells that sourced the old bashrc.
    return f'''# Generated by Maylang update.py; source this file from Bash.
_maylang_refresh_path() {{
    local remaining="$PATH" entry cleaned="" first=1
    while true; do
        entry="${{remaining%%:*}}"
        case "$entry" in
            {shlex.quote(str(root))}/maylang-*/bin|{shlex.quote(str(root))}/current/bin|"$HOME"/.maylang/bin) ;;
            *)
                if [ "$first" = 1 ]; then cleaned="$entry"; first=0
                else cleaned="$cleaned:$entry"; fi
                ;;
        esac
        case "$remaining" in *:*) remaining="${{remaining#*:}}" ;; *) break ;; esac
    done
    export PATH={shlex.quote(str(root / 'current/bin'))}:"$cleaned"
}}
_maylang_refresh_path
unset -f _maylang_refresh_path
export MAYLANG_STDLIB={shlex.quote(str(root / 'current/stdlib'))}
maylang-update() {{
    python3 {shlex.quote(str(root / 'update.py'))} "$@" --root {shlex.quote(str(root))} --bashrc {shlex.quote(str(bashrc))} || return $?
    . {shlex.quote(str(root / 'env.sh'))}
    hash -r
}}
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('selection', nargs='?', default='latest',
                        help='latest (default), installed version, or extracted bundle directory')
    parser.add_argument('--root', type=Path, default=Path.home() / '.local/share/maylang',
                        help='directory containing extracted releases')
    parser.add_argument('--bashrc', type=Path, default=Path.home() / '.bashrc')
    parser.add_argument('--dry-run', action='store_true', help='show selection without changing files')
    args = parser.parse_args()
    root = args.root.expanduser().resolve()
    bashrc = args.bashrc.expanduser().resolve()
    bundle = select_bundle(root, args.selection)
    version = validate_bundle(bundle)
    current = root / 'current'
    if current.exists() and not current.is_symlink():
        raise ValueError(f'{current} exists and is not a symlink')
    original = bashrc.read_text() if bashrc.exists() else ''
    updated = bashrc_content(original, root, root / 'env.sh')
    if args.dry_run:
        print(f'Would select Maylang {version}: {bundle}')
        print(f'Would configure {bashrc} and {root / "env.sh"}')
        return
    root.mkdir(parents=True, exist_ok=True)
    # Some manually extracted bundles have lost their executable permissions.
    for name in TOOLS:
        binary = bundle / 'bin' / name
        binary.chmod(binary.stat().st_mode | 0o111)
    atomic_write(root / 'update.py', Path(__file__).read_text(), 0o755)
    atomic_write(root / 'env.sh', environment(root, bashrc))
    if updated != original:
        backup = bashrc.with_name(bashrc.name + '.maylang-backup')
        if bashrc.exists() and not backup.exists():
            shutil.copy2(bashrc, backup)
        atomic_write(bashrc, updated, bashrc.stat().st_mode & 0o777 if bashrc.exists() else 0o644)
    # Replace the link last so binaries and stdlib switch together.
    with tempfile.TemporaryDirectory(prefix='.current-', dir=root) as directory:
        link = Path(directory) / 'current'
        link.symlink_to(os.path.relpath(bundle, root), target_is_directory=True)
        link.replace(current)
    print(f'Using Maylang {version}: {bundle}')
    print(f'To refresh this shell: source {shlex.quote(str(root / "env.sh"))}')


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError) as error:
        print(f'maylang-update: {error}', file=sys.stderr)
        sys.exit(1)
